grant masarifi_migration to current_user with set true,inherit false;
set local role masarifi_migration;

-- Deactivate only the original demo identities. Preserve rows and all owner-linked records.
update public.financial_institutions set active=false where id in
 ('08000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002')
 and code in ('example-crescent-bank','example-palm-wallet');
update public.institution_senders set active=false where id in
 ('08000000-0000-4000-8000-000000000011','08000000-0000-4000-8000-000000000012')
 and sender_pattern in ('EXAMPLE-CRESCENT','EXAMPLE-PALM');
-- Sender identities are already represented by the governed redacted SA/AE corpus.
-- They identify a source for review, never establish posting authority by themselves.
insert into public.financial_institutions(id,country_code,name,code) values
 ('08000000-0000-4000-8000-000000000101','SA','Alinma Bank','alinma'),
 ('08000000-0000-4000-8000-000000000102','AE','Abu Dhabi Commercial Bank','adcb')
 on conflict(code) do nothing;
insert into public.institution_senders(id,institution_id,sender_pattern,display_label,priority)
 select v.id::uuid,i.id,v.sender,v.label,10 from (values
 ('08000000-0000-4000-8000-000000000111','alinma','alinma','Alinma Bank'),
 ('08000000-0000-4000-8000-000000000112','adcb','ADCBAlert','Abu Dhabi Commercial Bank')) v(id,code,sender,label)
 join public.financial_institutions i on i.code=v.code
 on conflict do nothing;
-- A new immutable rule release corrects qualified currencies without replaying imports.
insert into public.tracking_rule_releases(id,schema_version,engine_version,status,snapshot,content_hash,validated_hash,corpus_result,created_by,published_by,published_at,reason)
