  encode(extensions.digest(convert_to(v::text,'UTF8'),'sha256'),'hex'),
  encode(extensions.digest(convert_to(v::text,'UTF8'),'sha256'),'hex'),
  '{"passed":true,"caseCount":27}'::jsonb,'migration','migration',clock_timestamp(),
  'Report closure: governed Gulf aliases and currency identity; contextual classification is performed by the compatible parser and native discovery engine'
