e addition request","beneficiary added","إضافة مستفيد","اضافة مستفيد","transfers will be enabled"],"effects":{"status":"administrative","subtype":"administrative","direction":"unknown","disposition":"ignore"}},{"ruleKey":"exclude.promo","family":"exclusion","enabled":true,"priority":980,"any":["special offer","promo code","عرض خاص","عرض حصري","واحصل"],"effects":{"status":"administrative","subtype":"administrative","direction":"unknown","disposition":"ignore"}},{"ruleKey":"lifecycle.declined","family":"status","enabled":true,"priority":950,"any":["declined","rejected","insufficient funds","مرفوض","مرفوضة","رفضت","تم رفض","رفض العملية"],"effects":{"status":"declined","disposition":"ignore"}},{"ruleKey":"lifecycle.failed","family":"status","enabled":true,"priority":940,"any":["failed","unsuccessful","فشل","فشلت","لم تتم","غير ناجحة","غير ناجح","غير ناجحة"],"effects":{"status":"failed","disposition":"ignore"}},{"ruleKey":"lifecycle.cancelled","family":"status","enabled":true,"priority":930,"any":["cancelled","canceled","ملغاة","ملغى"],"effects":{"status":"cancelled","disposition":"ignore"}},{"ruleKey":"lifecycle.pending","family":"status","enabled":true,"priority":920,"any":["pending","will be credited","working days","قيد المعالجة","معلق","سيتم إيداع","سيتم ايداع","payment request","scheduled payment","payment due","will be transferred","سيتم تحويل","طلب دفع","دفع مستحق","deposit request","refund request","withdrawal request","transfer request","request for a refund","request for deposit","requested refund","طلب إيداع","طلب ايداع","طلب استرداد","طلب تحويل","طلب refund"],"effects":{"status":"pending","disposition":"review"}},{"ruleKey":"action.reversal","family":"action","enabled":true,"priority":850,"any":["reversed","reversal","عكس القيد","عكس العملية"],"effects":{"direction":"incoming","subtype":"reversal","status":"completed"}},{"ruleKey":"action.refund","family":"action","enabled":true,"priority":840,"any":["refund","refunded","استرداد","مسترد"],"effects":{"direction":"incoming","subtype":"refund","status":"completed"}},{"ruleKey":"action.salary","family":"action","enabled":true,"priority":830,"any":["salary","راتب"],"effects":{"direction":"incoming","subtype":"salary","status":"completed"}},{"ruleKey":"action.pos","family":"action","enabled":true,"priority":820,"any":["شراء عبر نقاط بيع","pos purchase"],"effects":{"direction":"outgoing","subtype":"pos_purchase","status":"completed"}},{"ruleKey":"action.online","family":"action","enabled":true,"priority":810,"any":["شراء إنترنت","شراء انترنت","online purchase","internet purchase"],"effects":{"direction":"outgoing","subtype":"online_purchase","status":"completed"}},{"ruleKey":"action.card","family":"action","enabled":true,"priority":800,"any":["used for"],"effects":{"direction":"outgoing","subtype":"card_purchase","status":"completed"}},{"ruleKey":"action.bill","family":"action","enabled":true,"priority":790,"any":["سدادك","bill payment","فاتورة"],"effects":{"direction":"outgoing","subtype":"bill_payment","status":"completed"}},{"ruleKey":"action.withdrawal","family":"action","enabled":true,"priority":780,"any":["cash withdrawal","withdrawal","withdrawn","سحب نقدي","سحب"],"effects":{"direction":"outgoing","subtype":"withdrawal","status":"completed"}},{"ruleKey":"action.transfer.sent","family":"action","enabled":true,"priority":770,"any":["transfer to","transferred to","outgoing transfer","تحويل صادر","تم تحويل","transfer sent","money sent successfully"],"effects":{"direction":"outgoing","subtype":"transfer_sent","status":"completed"}},{"ruleKey":"action.transfer.received","family":"action","enabled":true,"priority":760,"any":["transfer from","incoming transfer","تحويل وارد","تم استلام","transfer received","money received successfully"],"effects":{"direction":"incoming","subtype":"transfer_received","status":"completed"}},{"ruleKey":"action.debit","family":"action","enabled":true,"priority":750,"any":["dr. transaction","dr transaction","debit transaction","debited","خصم"],"effects":{"direction":"outgoing","subtype":"generic_debit","status":"completed"}},{"ruleKey":"action.purchase","family":"action","enabled":true,"priority":740,"any":["purchase","شراء","spent"],"effects":{"direction":"outgoing","subtype":"purchase","status":"completed"}},{"ruleKey":"action.payment","family":"action","enabled":true,"priority":730,"any":["paid","payment","charged","دفع","سداد"],"effects":{"direction":"outgoing","subtype":"payment","status":"completed"}},{"ruleKey":"action.fee","family":"action","enabled":true,"priority":755,"any":["fee","fees","service charge","commission","رسوم","عمولة"],"effects":{"direction":"outgoing","subtype":"fee","status":"completed"},"not":["purchase","used for","شراء","paid","dr. transaction","debited"]},{"ruleKey":"action.deposit","family":"action","enabled":true,"priority":710,"any":["deposit","deposited","إيداع","ايداع","تم إيداع","تم ايداع"],"effects":{"direction":"incoming","subtype":"deposit","status":"completed"}},{"ruleKey":"action.credit","family":"action","enabled":true,"priority":700,"any":["credited","cr. transaction","cr transaction","إضافة","اضافة"],"effects":{"direction":"incoming","subtype":"generic_credit","status":"completed"}}],"providers":[{"providerKey":"alinma","country":"SA","senders":["alinma"],"packages":[]},{"providerKey":"adcb","country":"AE","senders":["ADCBAlert"],"packages":[]},{"providerKey":"instapay","country":"EG","senders":[],"packages":["com.egyptianbanks.instapay"]},{"providerKey":"du","country":"AE","senders":["du"],"packages":[]}]}$tracking_pack$::jsonb v) snapshot
on conflict ((snapshot->>'releaseId')) do nothing;

insert into public.tracking_rule_entries(release_id,rule_key,family,enabled,priority,definition)
select r.id,e->>'ruleKey',e->>'family',(e->>'enabled')::boolean,(e->>'priority')::integer,e
from public.tracking_rule_releases r cross join lateral jsonb_array_elements(r.snapshot->'rules') e
where r.snapshot->>'releaseId'='bundled-report-closure-2026-10-24'
on conflict do nothing;

-- Preserve posting/review mode and any separately published administrator catalog.
update public.tracking_rule_channels c set release_id=r.id,version=c.version+1,updated_at=clock_timestamp()
from public.tracking_rule_releases r,public.tracking_rule_releases prior
where c.release_id=prior.id and prior.snapshot->>'releaseId' in ('bundled-sa-ae-eg-requests-2026-10-09','bundled-currency-identity-2026-10-18')
  and r.snapshot->>'releaseId'='bundled-report-closure-2026-10-24'
  and c.environment='default' and c.market='global' and c.channel='all';

reset role;
revoke masarifi_migration from current_user granted by current_user;
